#include <fstream>
#include <string>
#include <algorithm>
#define main original_ga_main
#include "../ga-cuda/main.cu"
#undef main
int main(){const int n=4096,cl=8,ql=32,threshold=3,r=20;uint32_t state=123;char chars[]={'A','C','T','G'};std::vector<char>bits(n+cl+ql),target(n+cl),query(ql),got(n);for(char&v:bits){state=state*1664525u+1013904223u;v=chars[state>>30];}std::copy(bits.begin(),bits.begin()+n+cl,target.begin());std::copy(bits.begin()+n+cl,bits.end(),query.begin());std::copy(query.begin(),query.begin()+cl,target.begin());std::vector<int>expected(n),artifact(n);for(int tid=0;tid<n;tid++)for(int i=0;i<=ql-cl;i++){int distance=0;for(int j=0;j<cl;j++)distance+=target[tid+j]!=query[i+j];if(distance<threshold){expected[tid]=1;break;}}
char *dt,*dq,*out;cudaMalloc(&dt,n+cl);cudaMalloc(&dq,ql);cudaMalloc(&out,n);cudaMemcpy(dt,target.data(),n+cl,cudaMemcpyHostToDevice);cudaMemcpy(dq,query.data(),ql,cudaMemcpyHostToDevice);auto launch=[&](){for(int pos=0;pos<n;pos+=1024)ga<<<4,256>>>(dt,dq,out+pos,1024,ql,cl,threshold,pos);};cudaMemset(out,0,n);launch();cudaDeviceSynchronize();bool all=true;for(int trial=1;trial<=5;trial++){cudaMemset(out,0,n);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<r;j++)launch();auto error=cudaDeviceSynchronize();double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/r;cudaMemcpy(got.data(),out,n,cudaMemcpyDeviceToHost);bool ok=error==cudaSuccess;for(int i=0;i<n;i++){artifact[i]=got[i];ok &= artifact[i]==expected[i];}all &=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/output_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)artifact.data(),n*4);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",n,r,path.c_str(),n);}puts(all?"PASS":"FAIL");return all?0:1;}
